-- 67 Signs of the Silk Road: every word on the signs is drawn from a .ttf
-- its font_id names (Noto, subset to these words), its glyphs baked the
-- first time it is drawn; the swing is a looping timeline. This only keeps
-- the captions. Generated by tools/gen_scenes.py.

script = { tick_rate = 30 }

local nav = require("nav")
local SCENE = "scenes/67-signs-of-the-silk-road.scene"
local captions = true

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
end
